#include <bits/stdc++.h>
using namespace std;

struct Edge { int to, rev, cap; };
vector<vector<Edge>> g;
vector<int> level, ptr;

void addEdge(int u, int v, int c) {
    g[u].push_back({v, (int)g[v].size(), c});
    g[v].push_back({u, (int)g[u].size()-1, 0});
}

bool bfsLevels(int s, int t) {
    fill(level.begin(), level.end(), -1);
    queue<int> q;
    level[s] = 0;
    q.push(s);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (auto &e : g[u]) {
            if (e.cap > 0 && level[e.to] == -1) {
                level[e.to] = level[u] + 1;
                q.push(e.to);
            }
        }
    }
    return level[t] != -1;
}

int dfsFlow(int u, int t, int f) {
    if (u == t) return f;
    for (int &i = ptr[u]; i < (int)g[u].size(); ++i) {
        Edge &e = g[u][i];
        if (e.cap > 0 && level[e.to] == level[u] + 1) {
            int pushed = dfsFlow(e.to, t, min(f, e.cap));
            if (pushed) {
                e.cap -= pushed;
                g[e.to][e.rev].cap += pushed;
                return pushed;
            }
        }
    }
    return 0;
}

int maxFlow(int s, int t) {
    int total = 0;
    level.assign(t+1, -1);
    ptr.assign(t+1, 0);
    while (bfsLevels(s, t)) {
        fill(ptr.begin(), ptr.end(), 0);
        int pushed;
        while ((pushed = dfsFlow(s, t, 10000)) > 0) total += pushed;
    }
    return total;
}

int n, T, sinkNode;
int srcCap[10][10], snkCap[10][10], srcId[10][10], snkId[10][10];
int plant[10][10][61];
const int dr[4] = {0,0,-1,1};
const int dc[4] = {-1,1,0,0};

bool ok(int r, int c) {
    return r >= 0 && r < n && c >= 0 && c < n;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> T;
    vector<string> grid(n);
    for (int i = 0; i < n; ++i) cin >> grid[i];

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] == 'Y' || grid[i][j] == 'Z') {
                plant[i][j][0] = grid[i][j] - 'X';
                srcCap[i][j] = 0;
            } else {
                plant[i][j][0] = 0;
                srcCap[i][j] = grid[i][j] - '0';
            }
        }

    for (int i = 0; i < n; ++i) cin >> grid[i];

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] == 'Y' || grid[i][j] == 'Z') {
                plant[i][j][0] = grid[i][j] - 'X';
                snkCap[i][j] = 0;
            } else {
                plant[i][j][0] = 0;
                snkCap[i][j] = grid[i][j] - '0';
            }
        }

    for (int tm = 1; tm <= T; ++tm) {
        for (int i = 0; i < n; ++i)
            for (int j = 0; j < n; ++j)
                plant[i][j][tm] = plant[i][j][tm-1];

        for (int i = 0; i < n; ++i)
            for (int j = 0; j < n; ++j)
                if (plant[i][j][tm-1] == 2)
                    for (int d = 0; d < 4; ++d) {
                        int ni = i + dr[d], nj = j + dc[d];
                        if (ok(ni,nj) && plant[ni][nj][tm-1] == 0)
                            plant[ni][nj][tm] = 2;
                    }
    }

    memset(srcId, -1, sizeof(srcId));
    memset(snkId, -1, sizeof(snkId));
    sinkNode = 1;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (srcCap[i][j] != 0) srcId[i][j] = sinkNode++;

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (snkCap[i][j] != 0) snkId[i][j] = sinkNode++;

    g.assign(sinkNode + 1, vector<Edge>());

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) {
            if (srcCap[i][j] == 0) continue;
            queue<pair<int,pair<int,int>>> q;
            q.push({0, {i, j}});
            vector<vector<bool>> vis(n, vector<bool>(n, false));
            vis[i][j] = true;
            int src = srcId[i][j];
            while (!q.empty()) {
                auto cur = q.front(); q.pop();
                int tm = cur.first;
                int r = cur.second.first;
                int c = cur.second.second;
                if (snkCap[r][c] != 0) addEdge(src, snkId[r][c], 10000);
                if (tm == T) continue;
                if (plant[r][c][tm] != 0) continue;
                for (int d = 0; d < 4; ++d) {
                    int nr = r + dr[d], nc = c + dc[d];
                    if (ok(nr,nc) && plant[nr][nc][tm] == 0 && !vis[nr][nc]) {
                        vis[nr][nc] = true;
                        q.push({tm+1, {nr, nc}});
                    }
                }
            }
        }

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) {
            if (srcCap[i][j] != 0) addEdge(0, srcId[i][j], srcCap[i][j]);
            if (snkCap[i][j] != 0) addEdge(snkId[i][j], sinkNode, snkCap[i][j]);
        }

    cout << maxFlow(0, sinkNode) << '\n';
    return 0;
}
